/* Account profiles, privacy and earned-badge display. No provider details. */
(() => {
 'use strict';
 let app=null,identity='',epoch=0,cached=null,editor=null,dirty=false,busy=false,discardPrompt=false,writeVersion=0,writeSerial=0;
 const $=id=>document.getElementById(id),state=()=>app?.state||{},esc=value=>app.esc(value);
 const paths={moon:'M17 3a9 9 0 1 0 4 14A9 9 0 0 1 17 3Z',orbit:'M4 12a8 8 0 1 0 16 0 8 8 0 1 0-16 0M2 16 22 8',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',leaf:'M20 3C8 2 3 8 5 16c7 7 15 0 15-13ZM5 20 16 8',ghost:'M5 20V9a7 7 0 0 1 14 0v11l-4-2-3 2-3-2-4 2M9 9v2m6-2v2'};
 const mediaURL=media=>media&&/^\/api\/media\/[a-f0-9]{64}$/.test(media.url||'')?media.url:null;
 const avatar=value=>{const profile=value&&typeof value==='object'?value:{avatar:value},url=mediaURL(profile.avatarMedia),mark=`<svg class="vp-avatar-mark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${paths[profile.avatar]||paths.moon}"/></svg>`;return url?`<span class="vp-avatar-image">${mark}<img src="${url}" alt="" loading="lazy" decoding="async" data-vp-photo></span>`:mark;};
 const art=(id,mini=false)=>window.VoidCosmetics?.art?.(id,mini)||avatar('spark');
 function sync(){const id=state().account?.id||'';if(id!==identity){window.VoidProfileMedia?.disposeAll();identity=id;epoch++;writeVersion++;writeSerial++;cached=null;editor=null;dirty=false;busy=false;discardPrompt=false;}}
 function guard(){sync();const id=identity,version=epoch,parent=app.guard();return ()=>version===epoch&&id===state().account?.id&&parent();}
 const clean=p=>({displayName:p.displayName||'',bio:p.bio||'',status:p.status||'',avatar:p.avatar||'moon',banner:p.banner||'midnight',accent:p.accent||'ice',detailsVisibility:p.detailsVisibility||'shared',collectionVisibility:p.collectionVisibility||'shared',animationEnabled:!!p.animationEnabled,badgeOrder:p.badgeOrder||[],avatarMediaId:p.avatarMediaId||p.avatarMedia?.id||null,bannerMediaId:p.bannerMediaId||p.bannerMedia?.id||null});
 function projection(value){const profile=editor?.profile||{};return {...profile,...value,avatarMedia:value.avatarMediaId?(editor?.uploads?.get(value.avatarMediaId)||profile.avatarMedia):null,bannerMedia:value.bannerMediaId?(editor?.uploads?.get(value.bannerMediaId)||profile.bannerMedia):null};}
 function cancelStaged(keep=[]){if(!editor?.uploads)return;for(const [id]of editor.uploads){if(!keep.includes(id))app.request('/api/media/'+id+'/cancel',{}).catch(()=>{});}}
 function profileCard(profile,{compact=false,editing=false}={}){
  const p=profile||state().account||{},safeBanner=['midnight','blueprint','eclipse','noise','orchid'].includes(p.banner)?p.banner:'midnight',safeAccent=['ice','lilac','jade','oxide','gold'].includes(p.accent)?p.accent:'ice',shownAwards=Array.isArray(p.badgeOrder)?p.badgeOrder.map(id=>(p.earnedBadges||[]).find(b=>b.badge_id===id)).filter(Boolean):(p.earnedBadges||[]);
  return `<section class="vp-card ${compact?'vp-compact':''}" data-accent="${safeAccent}" data-banner="${safeBanner}" data-animated="${p.animationEnabled===true}"><div class="vp-banner" aria-hidden="true">${mediaURL(p.bannerMedia)?`<img class="vp-banner-image" src="${mediaURL(p.bannerMedia)}" alt="" loading="lazy" decoding="async" data-vp-photo>`:'<i></i><b></b>'}</div><div class="vp-content"><span class="vp-avatar">${avatar(p)}</span><div class="vp-name-line"><h2>${esc(p.displayName||'Profile')}</h2>${p.equippedId?`<span class="vp-equipped" title="Equipped decoration">${art(p.equippedId,true)}</span>`:''}</div><p class="vp-username">@${esc(p.username||state().account?.username||'')}</p>${p.role==='platform-owner'?'<p class="vp-official">Platform owner <span>Verified server role</span></p>':''}${p.detailsVisible===false?'<p class="vp-private">This person keeps richer profile details private.</p>':`${p.status?`<p class="vp-status">${esc(p.status)}</p>`:''}<p class="vp-bio">${esc(p.bio||'No bio added.')}</p>`}${shownAwards.length?`<div class="vp-awards" aria-label="Earned badges">${shownAwards.slice(0,3).map(b=>`<button type="button" ${editing?'disabled':''} data-vp-award="${esc(b.badge_id)}" title="${esc(b.name)} — ${esc(b.issuer||'Server-verified requirement')}">${art(b.badge_id,true)}<span>${esc(b.name)}</span></button>`).join('')}</div>`:''}${!compact&&p.collectionVisible!==false&&p.showcase?.length?`<div class="vp-showcase"><h3>Gift showcase</h3><div>${p.showcase.map(g=>`<article>${art(g.catalog_id)}<span>${esc(g.name||g.catalog_id.replace(/^gift-/,'').replaceAll('-',' '))}</span>${g.sender_username?`<small>From @${esc(g.sender_username)}</small>`:''}</article>`).join('')}</div></div>`:''}${!compact&&p.collectionVisible===false?'<p class="vp-private">This collection is private.</p>':''}${editing?'':'<div class="vp-card-actions">'+(p.id===identity?'<button class="vh-secondary" data-vp-action="edit">Edit profile</button><button class="vh-secondary" data-vp-action="popover">Compact preview</button>':`<button class="vh-secondary" data-vp-action="full" data-account="${esc(p.id)}">Full profile</button>`)+(p.collectionVisible!==false?`<button class="vh-secondary" data-vp-action="collection" data-account="${esc(p.id||identity)}">View gifts</button>`:'')+'</div>'}</div></section>`;
 }
 function profileHTML(account){sync();return profileCard(cached||{...account,id:account.id,detailsVisible:true,collectionVisible:true});}
 function error(error){const node=$('vp-error');if(node)node.textContent=error.message||'The profile could not be saved. Your edits are still here.';else app.announce(error.message||'The profile is unavailable.');}
 async function refresh(){sync();if(!identity)return;const current=guard(),version=writeVersion;try{const response=await app.request('/api/profiles/me');if(!current()||version!==writeVersion)return;cached=response.profile;Object.assign(state().account,{avatarMedia:cached.avatarMedia,bannerMedia:cached.bannerMedia});if(!editor&&!state().secureRoomId)app.render();}catch(_){/* details remain an explicit load/retry action */}}
 async function openProfile(id=identity,compact=false){if(id===identity&&dirty)return beforeCloseDialog();const current=guard(),ticket=app.showDialog('Profile','', '<div id="vp-profile-result" role="status">Loading profile…</div>');try{const response=await app.request('/api/profiles/'+encodeURIComponent(id));if(!current()||ticket!==state().dialogGeneration)return;const node=$('vp-profile-result');if(node)node.innerHTML=profileCard(response.profile,{compact});if(id===identity)cached=response.profile;}catch(reason){if(current()&&ticket===state().dialogGeneration){const node=$('vp-profile-result');if(node)node.innerHTML='<p class="vp-private">This profile is unavailable to your account.</p>';}}}
 const options=(values,value)=>values.map(v=>`<option value="${v}" ${value===v?'selected':''}>${esc(v[0].toUpperCase()+v.slice(1))}</option>`).join('');
 async function mountCrop(file,kind,clientId=crypto.randomUUID()){
  if(!editor||!file)return;const current=guard(),snapshot=editor,ticket=state().dialogGeneration;
  window.VoidProfileMedia?.disposeAll();snapshot.cropFile=file;snapshot.cropKind=kind;snapshot.cropClientId=clientId;dirty=true;
  const target=$('vp-crop-root');if(!target)return;const selected=()=>current()&&editor===snapshot&&ticket===state().dialogGeneration&&snapshot.cropClientId===clientId;
  try{
   if(!window.VoidProfileMedia)throw Error('Image tools could not load. Refresh and retry.');
   await window.VoidProfileMedia.mountCrop({container:target,file,kind,isCurrent:selected,
    onApply:async blob=>{const asset=await window.VoidProfileMedia.upload({request:app.request,blob,kind,clientId,filename:kind+'.png',isCurrent:selected});if(!selected())return;const oldId=snapshot.draft[kind+'MediaId'];snapshot.uploads.set(asset.id,asset);snapshot.draft[kind+'MediaId']=asset.id;snapshot.cropFile=null;snapshot.cropKind=null;snapshot.cropClientId=null;if(oldId&&snapshot.uploads.has(oldId)&&oldId!==asset.id){app.request('/api/media/'+oldId+'/cancel',{}).catch(()=>{});snapshot.uploads.delete(oldId);}updatePreview($('vp-editor'));app.announce('Image uploaded. Save profile to make it visible.');},
    onCancel:()=>{if(!selected())return;snapshot.cropFile=null;snapshot.cropKind=null;snapshot.cropClientId=null;updatePreview($('vp-editor'));},onError:error});
  }catch(reason){if(selected()){snapshot.cropFile=null;snapshot.cropKind=null;snapshot.cropClientId=null;error(reason);updatePreview($('vp-editor'));}}
 }
 function showEditor(profile,draft=clean(profile)){
  const previous=editor;window.VoidProfileMedia?.disposeAll();editor={profile,committed:clean(profile),draft,uploads:previous?.profile?.id===profile.id?previous.uploads||new Map():new Map(),cropFile:previous?.cropFile||null,cropKind:previous?.cropKind||null,cropClientId:previous?.cropClientId||null};discardPrompt=false;dirty=!!editor.cropFile||JSON.stringify(clean(draft))!==JSON.stringify(clean(editor.committed));
  app.showDialog('Edit profile','Your public identity and profile visibility. Account email and sign-in details never appear here.',`<form class="vp-editor" id="vp-editor" data-vp-form="profile"><div id="vp-live-preview">${profileCard(projection(draft),{compact:true,editing:true})}</div><p id="vp-save-state" class="vp-save-state" role="status">${dirty?'Unsaved changes':'All changes saved'}</p><section class="vp-media-fields" aria-label="Profile images"><div><h3>Avatar</h3><label class="vh-secondary vp-file-label">Upload image<input type="file" data-vp-file="avatar" accept="image/png,image/jpeg,image/webp"></label><button type="button" class="vh-text-button" data-vp-action="reset-avatar">Use preset avatar</button></div><div><h3>Banner</h3><label class="vh-secondary vp-file-label">Upload image<input type="file" data-vp-file="banner" accept="image/png,image/jpeg,image/webp"></label><button type="button" class="vh-text-button" data-vp-action="reset-banner">Use preset banner</button></div><p class="vp-fine">Still PNG, JPEG or WebP · up to 8 MiB and 16 megapixels. Cropped locally before upload. Your avatar follows profile access; your banner follows profile-details visibility.</p></section><div id="vp-crop-root"></div><label class="vh-field">Display name<input name="displayName" value="${esc(draft.displayName)}" minlength="2" maxlength="32" required></label><label class="vh-field">Bio<textarea name="bio" rows="3" maxlength="240">${esc(draft.bio)}</textarea></label><label class="vh-field">Status<input name="status" value="${esc(draft.status)}" maxlength="80"></label><div class="vp-field-grid"><label class="vh-field">Avatar<select name="avatar">${options(['moon','orbit','spark','leaf','ghost'],draft.avatar)}</select></label><label class="vh-field">Banner<select name="banner">${options(['midnight','blueprint','eclipse','noise','orchid'],draft.banner)}</select></label><label class="vh-field">Accent<select name="accent">${options(['ice','lilac','jade','oxide','gold'],draft.accent)}</select></label><label class="vh-field">Profile details<select name="detailsVisibility">${options(['shared','friends','private','public'],draft.detailsVisibility)}</select></label><label class="vh-field">Gift collection<select name="collectionVisibility">${options(['shared','friends','private','public'],draft.collectionVisibility)}</select></label></div><p class="vp-fine">Shared means accepted friends and people in a community you both belong to. A block overrides public visibility.</p><label class="vp-check"><input type="checkbox" name="animationEnabled" ${draft.animationEnabled?'checked':''}>Allow this profile’s restrained banner animation</label><fieldset class="vp-badge-order"><legend>Earned badge display order</legend><p>Choose up to three valid earned badges. Empty slots keep them off your profile. Free decorations are equipped in the collection.</p>${[0,1,2].map(index=>`<label>Slot ${index+1}<select name="badge${index}"><option value="">Empty</option>${(profile.earnedBadges||[]).map(b=>`<option value="${esc(b.badge_id)}" ${draft.badgeOrder[index]===b.badge_id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>`).join('')}</fieldset><p class="vp-error" id="vp-error" role="alert"></p><div class="vp-actions"><button class="vh-primary" type="submit">Save profile</button><button class="vh-secondary" type="button" data-vp-action="discard">Discard changes</button></div></form>`);
  if(editor.cropFile)mountCrop(editor.cropFile,editor.cropKind,editor.cropClientId);
 }
 async function edit(){sync();if(dirty&&editor)return showEditor(editor.profile,editor.draft||editor.pending||clean(editor.profile));const current=guard(),ticket=app.showDialog('Edit profile','', '<p role="status">Loading saved profile…</p>');try{const result=await app.request('/api/profiles/me');if(!current()||ticket!==state().dialogGeneration)return;cached=result.profile;showEditor(result.profile);}catch(reason){if(current()&&ticket===state().dialogGeneration)error(reason);}}
 function formValue(form){const data=new FormData(form);return {avatarMediaId:editor?.draft?.avatarMediaId||null,bannerMediaId:editor?.draft?.bannerMediaId||null,displayName:String(data.get('displayName')||''),bio:String(data.get('bio')||''),status:String(data.get('status')||''),avatar:String(data.get('avatar')||'moon'),banner:String(data.get('banner')||'midnight'),accent:String(data.get('accent')||'ice'),detailsVisibility:String(data.get('detailsVisibility')||'shared'),collectionVisibility:String(data.get('collectionVisibility')||'shared'),animationEnabled:data.get('animationEnabled')==='on',badgeOrder:[0,1,2].map(i=>data.get('badge'+i)).filter(Boolean)};}
 function updatePreview(form){if(!editor)return;const value=formValue(form);editor.draft=value;dirty=!!editor.cropFile||JSON.stringify(clean(value))!==JSON.stringify(clean(editor.committed));const preview=$('vp-live-preview');if(preview)preview.innerHTML=profileCard(projection(value),{compact:true,editing:true});const label=$('vp-save-state');if(label)label.textContent=dirty?'Unsaved changes':'All changes saved';}
 async function save(form){if(busy)return;if(editor?.cropFile){error(Error('Upload or cancel the selected crop before saving the profile.'));return;}const current=guard(),ticket=state().dialogGeneration,payload=formValue(form),serial=++writeSerial,button=form.querySelector('[type="submit"]');busy=true;writeVersion++;if(button)button.disabled=true;try{const result=await app.request('/api/profiles/me',payload);if(!current()||ticket!==state().dialogGeneration||!form.isConnected)return;cached=result.profile;Object.assign(state().account,{displayName:cached.displayName,bio:cached.bio,status:cached.status,avatar:cached.avatar,avatarMedia:cached.avatarMedia,bannerMedia:cached.bannerMedia});cancelStaged([cached.avatarMedia?.id,cached.bannerMedia?.id,editor.draft.avatarMediaId,editor.draft.bannerMediaId]);editor.uploads.delete(cached.avatarMedia?.id);editor.uploads.delete(cached.bannerMedia?.id);editor.profile=cached;editor.committed=clean(cached);const latest=formValue(form);dirty=!!editor.cropFile||JSON.stringify(clean(latest))!==JSON.stringify(clean(editor.committed));const node=$('vp-save-state');if(node)node.textContent=dirty?'Saved the submitted version. Newer edits are still unsaved.':'Profile saved';updatePreview(form);if(!dirty)app.announce('Profile saved.');else app.announce('Earlier profile changes saved. Your newer edits are still unsaved.');window.VoidCosmetics?.refresh?.();}catch(reason){if(current()&&ticket===state().dialogGeneration)error(reason);}finally{if(serial===writeSerial)busy=false;if(current()&&button?.isConnected)button.disabled=false;}}
 function beforeCloseDialog(){if(!dirty||!editor)return true;if(discardPrompt)return false;const form=$('vp-editor');if(!form)return true;const value=formValue(form),profile=editor.profile;discardPrompt=true;window.VoidProfileMedia?.disposeAll();app.showDialog('Discard profile changes?','Your newer edits have not been saved.', '<div class="vp-actions"><button class="vh-danger" data-vp-action="confirm-discard">Discard changes</button><button class="vh-secondary" data-vp-action="keep-editing">Keep editing</button></div>');editor.pending=value;editor.profile=profile;return false;}
 async function viewCollection(id,offset=0){const current=guard(),ticket=app.showDialog('Gift collection','The owner controls who can see this collection.', '<div id="vp-collection" role="status">Loading collection…</div>');try{const result=await app.request('/api/cosmetics/collections/'+encodeURIComponent(id)+'?offset='+offset);if(!current()||ticket!==state().dialogGeneration)return;const node=$('vp-collection');if(node)node.innerHTML=result.instances.map(item=>`<article class="vp-collection-item">${art(item.catalog_id)}<span>${esc(item.name||item.catalog_id.replace(/^gift-/,'').replaceAll('-',' '))}</span></article>`).join('')||'<p class="vp-private">No gift instances in this collection.</p>';if(result.total>30)node?.insertAdjacentHTML('beforeend',`<div class="vp-actions"><button class="vh-secondary" data-vp-action="collection-page" data-account="${esc(id)}" data-offset="${Math.max(0,offset-30)}" ${offset?'':'disabled'}>Previous</button><span>${offset+1}–${Math.min(offset+30,result.total)} of ${result.total}</span><button class="vh-secondary" data-vp-action="collection-page" data-account="${esc(id)}" data-offset="${offset+30}" ${result.page.hasMore?'':'disabled'}>Next</button></div>`);}catch(reason){if(current()&&ticket===state().dialogGeneration){const node=$('vp-collection');if(node)node.textContent='This collection is private or unavailable.';}}}
 function action(name,button){if(name==='edit')return edit();if(name==='popover')return openProfile(identity,true);if(name==='full')return openProfile(button.dataset.account||identity);if(name==='collection-page')return viewCollection(button.dataset.account,Number(button.dataset.offset)||0);if(name==='collection')return viewCollection(button.dataset.account||identity);if(name==='discard')return beforeCloseDialog();if(name==='keep-editing'&&editor)return showEditor(editor.profile,editor.pending||clean(editor.profile));if((name==='reset-avatar'||name==='reset-banner')&&editor){const kind=name.slice(6),id=editor.draft[kind+'MediaId'];editor.draft[kind+'MediaId']=null;if(editor.uploads.has(id)){app.request('/api/media/'+id+'/cancel',{}).catch(()=>{});editor.uploads.delete(id);}if(editor.cropKind===kind){window.VoidProfileMedia?.disposeAll();editor.cropFile=null;editor.cropKind=null;}updatePreview($('vp-editor'));return;}if(name==='confirm-discard'){cancelStaged();window.VoidProfileMedia?.disposeAll();dirty=false;editor=null;discardPrompt=false;app.closeDialog();}}
 function init(bridge){if(app)return;app=bridge;sync();document.addEventListener('error',event=>{if(event.target.matches?.('img[data-vp-photo]'))event.target.remove();},true);document.addEventListener('click',event=>{const button=event.target.closest('[data-vp-action],[data-vp-award]');if(!button||!state().account)return;event.preventDefault();if(button.dataset.vpAward)return window.VoidCosmetics?.badgeDirectory?.();Promise.resolve(action(button.dataset.vpAction,button)).catch(error);});document.addEventListener('submit',event=>{if(event.target.dataset.vpForm!=='profile'||!state().account)return;event.preventDefault();save(event.target);});document.addEventListener('change',event=>{if(event.target.dataset.vpFile&&state().account&&editor){const file=event.target.files?.[0];if(file)mountCrop(file,event.target.dataset.vpFile);event.target.value='';}});for(const type of ['input','change'])document.addEventListener(type,event=>{const form=event.target.closest('[data-vp-form="profile"]');if(form)updatePreview(form);});window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});}
 const extension={id:'profiles',init,profileHTML,openProfile,openPopover:id=>openProfile(id,true),hasUnsavedChanges:()=>dirty,beforeCloseDialog,handles:name=>name==='profile'||name==='profile-view',handleAction:name=>{if(name==='profile'){edit();return true;}if(name==='profile-view'){openProfile(identity);return true;}return false;},onAccount:refresh,onLock(){identity='';epoch++;writeVersion++;writeSerial++;cached=null;editor=null;dirty=false;busy=false;discardPrompt=false;window.VoidProfileMedia?.disposeAll();}};
 window.VoidProfilesPanel=Object.freeze({extension,openProfile,edit,profileCard,avatar});
 function register(){if(window.VoidHome?.registerExtension)window.VoidHome.registerExtension(extension);}
 window.addEventListener('voidline:home-ready',register,{once:true});register();
})();
